    private async Task<(HttpClient,Guid)> Login(UserRole role) {
        using var scope=fixture.App.Services.CreateScope();var auth=scope.ServiceProvider.GetRequiredService<AuthService>();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var email=$"wh-{Guid.NewGuid():N}@example.com";var registered=(await auth.Register(new("Warehouse operator",email,"WarehouseTest123!"),Ct))!;
        (await db.Users.FindAsync([registered.Id],Ct))!.Role=role;await db.SaveChangesAsync(Ct);var token=(await auth.Login(new(email,"WarehouseTest123!"),Ct))!;
