    }
    private async Task<T> Body<T>(HttpResponseMessage r,HttpStatusCode status=HttpStatusCode.OK) {Assert.True(status==r.StatusCode, $"Expected {status}, actual {r.StatusCode}: " + await r.Content.ReadAsStringAsync(Ct) + string.Join("\n",fixture.App.Logs.Messages.Where(m=>m.Contains("Unexpected failure")).TakeLast(1)));return(await r.Content.ReadFromJsonAsync<T>(Json,Ct))!;}
    private async Task<WarehouseResponse> Warehouse() => await Body<WarehouseResponse>(await client.PostAsJsonAsync("/api/warehouses",new WarehouseRequest($"W-{Guid.NewGuid():N}","Warehouse","private-description","Location"),Ct),HttpStatusCode.Created);
    private async Task<Product> Product() {using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var c=new Category{Name="Warehouse category"};var p=new Product{Name=$"Stock {Guid.NewGuid():N}",CategoryId=c.Id,Price=10,IsActive=true};db.AddRange(c,p);await db.SaveChangesAsync(Ct);return p;}
    private async Task Stock(Guid w,Guid p,int qty) => Assert.Equal(HttpStatusCode.OK,(await client.PostAsJsonAsync($"/api/warehouses/{w}/inventory/{p}/stock-in",new {quantity=qty,reason="Supply"},Ct)).StatusCode);
