    [Fact] public async Task Warehouse_normalization_unique_edit_status_and_pagination() {var w=await Warehouse();Assert.Equal(w.Code.ToUpperInvariant(),w.Code);Assert.Equal(HttpStatusCode.Conflict,(await client.PostAsJsonAsync("/api/warehouses",new WarehouseRequest($" {w.Code.ToLower()} ","Duplicate","",""),Ct)).StatusCode);await Body<WarehouseResponse>(await client.PutAsJsonAsync($"/api/warehouses/{w.Id}",new WarehouseRequest(w.Code,"Edited","",""),Ct));await Body<WarehouseResponse>(await client.PutAsJsonAsync($"/api/warehouses/{w.Id}/status",new{isActive=false},Ct));var page=await client.GetFromJsonAsync<ReportPage<WarehouseResponse>>($"/api/warehouses?search={w.Code}&isActive=false&pageSize=1",Ct);Assert.Equal(w.Id,Assert.Single(page!.Items).Id);}
    [Fact] public async Task Concurrent_default_changes_leave_one_default_without_stock_movement() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,7);var results=await Task.WhenAll(client.PostAsync($"/api/warehouses/{a.Id}/set-default",null,Ct),client.PostAsync($"/api/warehouses/{b.Id}/set-default",null,Ct));Assert.All(results,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));var defaults=await client.GetFromJsonAsync<ReportPage<WarehouseResponse>>("/api/warehouses?isDefault=true",Ct);Assert.Single(defaults!.Items);Assert.Equal(7,await Balance(a.Id,p.Id));Assert.Equal(0,await Balance(b.Id,p.Id));Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/warehouses/{defaults.Items[0].Id}/status",new{isActive=false},Ct)).StatusCode);}
    [Fact] public async Task Stock_and_draft_operations_prevent_deactivation() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,1);Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/warehouses/{a.Id}/status",new{isActive=false},Ct)).StatusCode);await Transfer(a.Id,b.Id,(p.Id,1));Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/warehouses/{b.Id}/status",new{isActive=false},Ct)).StatusCode);}
