    [Fact] public async Task Draft_edit_cancel_never_moves_stock() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);var tr=await Transfer(a.Id,b.Id,(p.Id,4));Assert.Equal(10,await Balance(a.Id,p.Id));await Body<TransferResponse>(await client.PutAsJsonAsync($"/api/stock-transfers/{tr.Id}",new TransferRequest(a.Id,b.Id,[new(p.Id,8)],"edited"),Ct));var cancelled=await Body<TransferResponse>(await client.PostAsync($"/api/stock-transfers/{tr.Id}/cancel",null,Ct));Assert.Equal(TransferStatus.Cancelled,cancelled.Status);Assert.Equal(10,await Balance(a.Id,p.Id));Assert.Equal(0,await Balance(b.Id,p.Id));Assert.Equal(HttpStatusCode.Conflict,(await Complete(tr.Id)).StatusCode);}
    [Fact] public async Task Completion_conserves_total_creates_typed_movements_and_is_idempotent() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,100);var tr=await Transfer(a.Id,b.Id,(p.Id,30));var done=await Body<TransferResponse>(await Complete(tr.Id));Assert.Equal(TransferStatus.Completed,done.Status);Assert.Equal(actor,done.CompletedByUserId);Assert.NotNull(done.CompletedAt);Assert.Equal(70,await Balance(a.Id,p.Id));Assert.Equal(30,await Balance(b.Id,p.Id));Assert.Equal(100,await Total(p.Id));await Body<TransferResponse>(await Complete(tr.Id));var history=(await client.GetFromJsonAsync<List<MovementResponse>>($"/api/inventory/{p.Id}/movements",Json,Ct))!.Where(m=>m.StockTransferId==tr.Id).ToArray();Assert.Equal(2,history.Length);Assert.Contains(history,m=>m.WarehouseId==a.Id&&m.MovementType==MovementType.TransferOut&&m.QuantityBefore==100&&m.QuantityAfter==70);Assert.Contains(history,m=>m.WarehouseId==b.Id&&m.MovementType==MovementType.TransferIn&&m.QuantityBefore==0&&m.QuantityAfter==30);Assert.All(history,m=>{Assert.Equal("Transfer",m.ReferenceType);Assert.Null(m.ReferenceId);Assert.Null(m.GoodsReceiptId);});Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/stock-transfers/{tr.Id}",new TransferRequest(a.Id,b.Id,[new(p.Id,1)],""),Ct)).StatusCode);}
    [Fact] public async Task Multi_line_insufficiency_rolls_back_every_balance_and_movement() {var a=await Warehouse();var b=await Warehouse();var p=await Product();var q=await Product();await Stock(a.Id,p.Id,20);await Stock(a.Id,q.Id,1);var tr=await Transfer(a.Id,b.Id,(p.Id,10),(q.Id,2));Assert.Equal(HttpStatusCode.Conflict,(await Complete(tr.Id)).StatusCode);Assert.Equal(20,await Balance(a.Id,p.Id));Assert.Equal(1,await Balance(a.Id,q.Id));Assert.Equal(0,await Balance(b.Id,p.Id));using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();Assert.False(await db.InventoryMovements.AnyAsync(m=>m.StockTransferId==tr.Id,Ct));Assert.Equal(TransferStatus.Draft,(await db.StockTransfers.FindAsync([tr.Id],Ct))!.Status);Assert.False(await db.AuditLogs.AnyAsync(l=>l.EntityId==tr.Id&&l.Action=="TransferComplete",Ct));}
    [Fact] public async Task Two_competing_transfers_80_and_60_from_100_have_one_winner() {var a=await Warehouse();var b=await Warehouse();var c=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,100);var x=await Transfer(a.Id,b.Id,(p.Id,80));var y=await Transfer(a.Id,c.Id,(p.Id,60));var results=await Task.WhenAll(Complete(x.Id),Complete(y.Id));Assert.Single(results,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(results,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(100,await Total(p.Id));Assert.True(await Balance(a.Id,p.Id)>=0);}
    [Fact] public async Task Concurrent_repeat_completion_moves_stock_once() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);var tr=await Transfer(a.Id,b.Id,(p.Id,7));Assert.All(await Task.WhenAll(Complete(tr.Id),Complete(tr.Id)),r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));Assert.Equal(3,await Balance(a.Id,p.Id));Assert.Equal(7,await Balance(b.Id,p.Id));}
    [Fact] public async Task Transfer_and_manual_out_share_lock_and_never_overspend() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);var tr=await Transfer(a.Id,b.Id,(p.Id,8));var results=await Task.WhenAll(Complete(tr.Id),client.PostAsJsonAsync($"/api/warehouses/{a.Id}/inventory/{p.Id}/stock-out",new{quantity=6,reason="Manual"},Ct));Assert.Single(results,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(results,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.True(await Balance(a.Id,p.Id)>=0);}
    [Fact] public async Task Sales_selected_warehouse_and_cancellation_original_after_default_switch() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var c=new Customer{Name="Warehouse customer"};db.Customers.Add(c);await db.SaveChangesAsync(Ct);var o=await Body<OrderResponse>(await client.PostAsJsonAsync("/api/orders",new OrderRequest(c.Id,[new(p.Id,4)],a.Id),Ct),HttpStatusCode.Created);await Body<OrderResponse>(await client.PutAsJsonAsync($"/api/orders/{o.Id}/status",new{status="Confirmed"},Ct));Assert.Equal(6,await Balance(a.Id,p.Id));await client.PostAsync($"/api/warehouses/{b.Id}/set-default",null,Ct);await Body<OrderResponse>(await client.PutAsJsonAsync($"/api/orders/{o.Id}/status",new{status="Cancelled"},Ct));Assert.Equal(10,await Balance(a.Id,p.Id));Assert.Equal(0,await Balance(b.Id,p.Id));}
    [Fact] public async Task Sales_cannot_borrow_stock_from_other_warehouse() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(b.Id,p.Id,100);using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var c=new Customer{Name="No split customer"};db.Customers.Add(c);await db.SaveChangesAsync(Ct);var o=await Body<OrderResponse>(await client.PostAsJsonAsync("/api/orders",new OrderRequest(c.Id,[new(p.Id,1)],a.Id),Ct),HttpStatusCode.Created);Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/orders/{o.Id}/status",new{status="Confirmed"},Ct)).StatusCode);Assert.Equal(100,await Balance(b.Id,p.Id));}
    [Fact] public async Task Receipt_destination_partial_and_warehouse_idempotency() {var a=await Warehouse();var b=await Warehouse();var p=await Product();var s=await Body<SupplierResponse>(await client.PostAsJsonAsync("/api/suppliers",new SupplierRequest($"S-{Guid.NewGuid():N}","Supplier","","","","",""),Ct),HttpStatusCode.Created);var po=await Body<PurchaseResponse>(await client.PostAsJsonAsync("/api/purchase-orders",new PurchaseRequest(s.Id,null,"",[new(p.Id,10,2)]),Ct),HttpStatusCode.Created);await client.PostAsync($"/api/purchase-orders/{po.Id}/submit",null,Ct);var key=Guid.NewGuid();Task<HttpResponseMessage> Receive(Guid warehouse,Guid operation,int qty) {var msg=new HttpRequestMessage(HttpMethod.Post,$"/api/purchase-orders/{po.Id}/receipts"){Content=JsonContent.Create(new ReceiptRequest([new(po.Items[0].Id,qty)],"",warehouse))};msg.Headers.Add("Idempotency-Key",operation.ToString());return client.SendAsync(msg,Ct);}var first=await Body<ReceiptResponse>(await Receive(a.Id,key,4),HttpStatusCode.Created);Assert.Equal(a.Id,first.WarehouseId);await Body<ReceiptResponse>(await Receive(a.Id,key,4));Assert.Equal(HttpStatusCode.Conflict,(await Receive(b.Id,key,4)).StatusCode);await Body<ReceiptResponse>(await Receive(b.Id,Guid.NewGuid(),6),HttpStatusCode.Created);Assert.Equal(4,await Balance(a.Id,p.Id));Assert.Equal(6,await Balance(b.Id,p.Id));Assert.Equal(10,await Total(p.Id));}
    [Fact] public async Task Database_guards_negative_duplicate_default_and_final_history() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,5);var tr=await Transfer(a.Id,b.Id,(p.Id,2));await Body<TransferResponse>(await Complete(tr.Id));using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"WarehouseInventories\" SET \"QuantityOnHand\"=-1 WHERE \"ProductId\"={p.Id}",Ct))).SqlState);Assert.Equal("23505",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"Warehouses\" SET \"IsDefault\"=true WHERE \"Id\"={a.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"StockTransferItems\" SET \"Quantity\"=99 WHERE \"StockTransferId\"={tr.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"InventoryMovements\" WHERE \"StockTransferId\"={tr.Id}",Ct))).SqlState);}
    [Fact] public async Task Reports_match_database_and_include_missing_zero_pairs() {var a=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,3);await client.PutAsJsonAsync($"/api/warehouses/{a.Id}/inventory/{p.Id}/minimum-level",new{minimumStockLevel=5},Ct);var r=await client.GetFromJsonAsync<WarehouseReport>("/api/reports/warehouses",Ct);using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();Assert.Equal(await db.WarehouseInventories.SumAsync(i=>(long)i.QuantityOnHand,Ct),r!.TotalUnits);Assert.Equal((long)await db.Warehouses.CountAsync(Ct)*await db.Products.CountAsync(Ct)-await db.WarehouseInventories.CountAsync(i=>i.QuantityOnHand>0,Ct),r.OutOfStockCombinations);var stock=await client.GetFromJsonAsync<ReportPage<WarehouseStock>>($"/api/warehouses/{a.Id}/inventory?search={Uri.EscapeDataString(p.Name)}&stockStatus=Low",Ct);Assert.Equal(p.Id,Assert.Single(stock!.Items).ProductId);}
    [Fact] public async Task Completion_audit_contains_warehouse_products_actor_once() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,5);var tr=await Transfer(a.Id,b.Id,(p.Id,2));await Body<TransferResponse>(await Complete(tr.Id));await Body<TransferResponse>(await Complete(tr.Id));var logs=await client.GetFromJsonAsync<AuditPage>("/api/audit-logs?entityName=StockTransfer&action=TransferComplete&pageSize=100",Ct);var audit=Assert.Single(logs!.Items,l=>l.EntityId==tr.Id);Assert.Equal(actor,audit.UserId);var text=JsonSerializer.Serialize(audit);Assert.Contains(p.Id.ToString(),text);Assert.Contains("quantity",text,StringComparison.OrdinalIgnoreCase);Assert.DoesNotContain("private-notes",text);}
    [Fact] public async Task Product_deactivated_after_draft_blocks_completion_without_movement() {var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,5);var tr=await Transfer(a.Id,b.Id,(p.Id,2));using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();(await db.Products.FindAsync([p.Id],Ct))!.IsActive=false;await db.SaveChangesAsync(Ct);Assert.Equal(HttpStatusCode.Conflict,(await Complete(tr.Id)).StatusCode);Assert.Equal(5,await Balance(a.Id,p.Id));Assert.Equal(0,await Balance(b.Id,p.Id));}
    [Fact] public async Task Audit_insert_database_failure_rolls_back_transfer_and_both_balances() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,5);var tr=await Transfer(a.Id,b.Id,(p.Id,2));
        using var scope=fixture.App.Services.CreateScope();var original=scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var accessor=new HttpContextAccessor{HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity([new("sub",actor.ToString()),new("name","Actor")],"test"))}};
        await using var failing=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(original.Database.GetConnectionString()).AddInterceptors(new RejectAudit()).Options,accessor);
        await Assert.ThrowsAsync<DbUpdateException>(()=>new TransferService(failing).Transition(tr.Id,true,actor,Ct));
        Assert.Equal(5,await Balance(a.Id,p.Id));Assert.Equal(0,await Balance(b.Id,p.Id));Assert.False(await original.InventoryMovements.AnyAsync(m=>m.StockTransferId==tr.Id,Ct));Assert.Equal(TransferStatus.Draft,(await original.StockTransfers.FindAsync([tr.Id],Ct))!.Status);
    }
    private sealed class RejectAudit : SaveChangesInterceptor {
        public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData data,InterceptionResult<int> result,CancellationToken ct=default) {foreach(var e in data.Context!.ChangeTracker.Entries<AuditLog>().Where(e=>e.State==EntityState.Added))e.Entity.UserId=Guid.NewGuid();return ValueTask.FromResult(result);}
    }
    [Fact] public async Task Transfer_and_sales_confirmation_share_stock_locks() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);var tr=await Transfer(a.Id,b.Id,(p.Id,8));using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var c=new Customer{Name="Race customer"};db.Customers.Add(c);await db.SaveChangesAsync(Ct);var o=await Body<OrderResponse>(await client.PostAsJsonAsync("/api/orders",new OrderRequest(c.Id,[new(p.Id,6)],a.Id),Ct),HttpStatusCode.Created);
        var responses=await Task.WhenAll(Complete(tr.Id),client.PutAsJsonAsync($"/api/orders/{o.Id}/status",new{status="Confirmed"},Ct));Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.True(await Balance(a.Id,p.Id)>=0);
    }
    [Fact] public async Task Separate_api_instances_complete_transfer_once() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);var tr=await Transfer(a.Id,b.Id,(p.Id,8));using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();await using var app=new TestApplication(db.Database.GetConnectionString()!);using var other=app.CreateClient();other.DefaultRequestHeaders.Authorization=client.DefaultRequestHeaders.Authorization;
        var responses=await Task.WhenAll(Complete(tr.Id),other.PostAsync($"/api/stock-transfers/{tr.Id}/complete",null,Ct));Assert.All(responses,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));Assert.Equal(2,await Balance(a.Id,p.Id));Assert.Equal(8,await Balance(b.Id,p.Id));
    }
    [Fact] public async Task Concurrent_receipt_and_transfer_preserve_quantities() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,10);var tr=await Transfer(a.Id,b.Id,(p.Id,8));
        var supplier=await Body<SupplierResponse>(await client.PostAsJsonAsync("/api/suppliers",new SupplierRequest($"R-{Guid.NewGuid():N}","Race supplier","","","","",""),Ct),HttpStatusCode.Created);
        var po=await Body<PurchaseResponse>(await client.PostAsJsonAsync("/api/purchase-orders",new PurchaseRequest(supplier.Id,null,"",[new(p.Id,3,2)]),Ct),HttpStatusCode.Created);await client.PostAsync($"/api/purchase-orders/{po.Id}/submit",null,Ct);
        var msg=new HttpRequestMessage(HttpMethod.Post,$"/api/purchase-orders/{po.Id}/receipts"){Content=JsonContent.Create(new ReceiptRequest([new(po.Items[0].Id,3)],"",a.Id))};msg.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());
        var results=await Task.WhenAll(Complete(tr.Id),client.SendAsync(msg,Ct));Assert.Equal(HttpStatusCode.OK,results[0].StatusCode);Assert.Equal(HttpStatusCode.Created,results[1].StatusCode);Assert.Equal(5,await Balance(a.Id,p.Id));Assert.Equal(8,await Balance(b.Id,p.Id));Assert.Equal(13,await Total(p.Id));
    }
    [Fact] public async Task Opposing_multi_product_transfers_use_common_lock_order() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();var q=await Product();foreach(var w in new[]{a.Id,b.Id})foreach(var product in new[]{p.Id,q.Id})await Stock(w,product,10);
        var x=await Transfer(a.Id,b.Id,(p.Id,3),(q.Id,5));var y=await Transfer(b.Id,a.Id,(q.Id,2),(p.Id,4));
        Assert.All(await Task.WhenAll(Complete(x.Id),Complete(y.Id)),r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));Assert.Equal(11,await Balance(a.Id,p.Id));Assert.Equal(7,await Balance(a.Id,q.Id));Assert.Equal(20,await Total(p.Id));Assert.Equal(20,await Total(q.Id));
    }
    [Fact] public async Task Company_limit_rejects_increase_in_another_warehouse() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();await Stock(a.Id,p.Id,int.MaxValue);
        Assert.Equal(HttpStatusCode.Conflict,(await client.PostAsJsonAsync($"/api/warehouses/{b.Id}/inventory/{p.Id}/stock-in",new{quantity=1,reason="Overflow"},Ct)).StatusCode);Assert.Equal(int.MaxValue,await Total(p.Id));Assert.Equal(0,await Balance(b.Id,p.Id));
    }
    [Fact] public async Task Draft_edit_replaces_and_adds_products_before_completion() {
        var a=await Warehouse();var b=await Warehouse();var p=await Product();var q=await Product();var r=await Product();await Stock(a.Id,q.Id,8);await Stock(a.Id,r.Id,9);var tr=await Transfer(a.Id,b.Id,(p.Id,2));
        var edited=await Body<TransferResponse>(await client.PutAsJsonAsync($"/api/stock-transfers/{tr.Id}",new TransferRequest(a.Id,b.Id,[new(q.Id,3),new(r.Id,4)],"Changed products"),Ct));Assert.Equal(2,edited.Items.Count);Assert.DoesNotContain(edited.Items,i=>i.ProductId==p.Id);await Body<TransferResponse>(await Complete(tr.Id));Assert.Equal(5,await Balance(a.Id,q.Id));Assert.Equal(3,await Balance(b.Id,q.Id));Assert.Equal(4,await Balance(b.Id,r.Id));
    }
